// === Tab: mySketch ===
let theShader
let Buffer
let img
let mask

function preload() {
	img = loadImage( "https://deckard.openprocessing.org/user324002/visual1820214/ha36fa4f28daa765149edd82274297dcb/cat.jpg" )
	mask = loadImage("https://openprocessing.org/sketch/1997127/files/circle.png" )
}

function setup() {
	createCanvas(600, 600, WEBGL)
	pixelDensity(1)
	Buffer = createFramebuffer({ format: FLOAT })
	theShader = createShader(vert, frag)
	noStroke()
	imageMode(CENTER)
	image(img, 0, 0)
}

function draw() {
	Buffer.draw(() => {
		shader(theShader)
		theShader.setUniform("iResolution", [width, height])
		theShader.setUniform("iPixelDensity", pixelDensity())
		theShader.setUniform("iCanvas", img)
		theShader.setUniform("iMask", mask)
		theShader.setUniform("iRadius", 7)
		theShader.setUniform("iSigma", 5)
		rect(0, 0, width, height)
	})
	image(Buffer, 0, 0)
	console.log(frameRate())
}


// === Tab: GaussianBlur ===
// noprotect

const GaussianBlur = `
	#ifndef PI
	#define PI 3.14159265359
	#endif

	// Gaussian function
	float gaussian(float x, float sigma) {
		return exp(-(x*x)/(2.*sigma*sigma))/(sqrt(2.*PI)*sigma);
	}

	// Gaussian blur
	vec3 GaussianBlur(vec2 uv, sampler2D img, float radius, float sigma, vec2 texelSize) {
		vec3 color = vec3(0.);
		float sum = 0.;
		for (float x = -radius; x <= radius; x++) {
			for (float y = -radius; y <= radius; y++) {
				float weight = gaussian(length(vec2(x, y)), sigma);
				color += texture(img, (uv + vec2(x, y) * texelSize)).xyz * weight;
				sum += weight;
			}
		}
		return color/sum;
	}

	// Gaussian blur based on a mask
	vec3 MaskGaussianBlur(vec2 uv, sampler2D img, sampler2D mask, float radius, float sigma, vec2 texelSize) {
		radius *= texture(mask, uv).x;
		vec3 color = vec3(0.);
		float sum = 0.;
		for (float x = -radius; x <= radius; x++) {
			for (float y = -radius; y <= radius; y++) {
				float weight = gaussian(length(vec2(x, y)), sigma);
				color += texture(img, (uv + vec2(x, y) * texelSize)).xyz * weight;
				sum += weight;
			}
		}
		return color/sum;
	}
`


// === Tab: shader ===
// noprotect

const frag = `#version 300 es
	precision mediump float;

	uniform vec2 iResolution;
	uniform float iPixelDensity;
	uniform sampler2D iCanvas;
	uniform sampler2D iMask;
	uniform float iRadius;
	uniform float iSigma;

	${ GaussianBlur }

	in vec2 vTexCoord;
	out vec4 fragColor;
	void main() {
		vec2 uv = vTexCoord;
		vec2 texelSize = 1./(iResolution.xy*iPixelDensity);
		vec3 color = MaskGaussianBlur(
			uv, iCanvas, iMask,
			iRadius, iSigma, texelSize
		);
		fragColor = vec4(color, 1.);
	}
`

const vert = `#version 300 es

	in vec3 aPosition;
	in vec2 aTexCoord;

	out vec2 vTexCoord;

	void main() {
		vTexCoord = aTexCoord;
		gl_Position = vec4(aPosition.xy*2.-1., aPosition.z, 1.);
	}
`

